import { gql } from "~/gql";

// Operation names are global across erxes; keep the plugin prefix. gql() is
// generated by codegen — write documents as static strings (no `${}`), and
// let Apollo hooks infer their types from the document.
export const STATUS_QUERY = gql(`
  query eduTechBraveStatus {
    eduTechBraveStatus {
      plugin
      version
      subdomain
      userId
      userEmail
    }
  }
`);

export const SETTINGS_QUERY = gql(`
  query eduTechBraveSettings {
    eduTechBraveSettings {
      slaHours {
        critical
        high
        medium
        low
      }
      organizationName
      escalationLevel1Label
      escalationLevel1Contact
      escalationLevel2Label
      escalationLevel2Contact
      helplineText
      updatedAt
      updatedBy
    }
  }
`);

export const SETTINGS_SAVE_MUTATION = gql(`
  mutation eduTechBraveSettingsSave($input: EduTechBraveSettingsInput!) {
    eduTechBraveSettingsSave(input: $input) {
      slaHours {
        critical
        high
        medium
        low
      }
      organizationName
      escalationLevel1Label
      escalationLevel1Contact
      escalationLevel2Label
      escalationLevel2Contact
      helplineText
      updatedAt
      updatedBy
    }
  }
`);
